package org.nonfood.oilplants.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.*;import org.nonfood.oilplants.service.ImageStorage;import java.io.*;
@WebServlet("/admin/plants/image") @MultipartConfig(maxFileSize=5242880,maxRequestSize=6291456) public class AdminImageUploadServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String id=r.getParameter("plantId");try{WebSupport.requireAdmin(r);long plantId=Long.parseLong(id);String alt=r.getParameter("altText"),source=r.getParameter("sourceNote");if(alt!=null&&alt.length()>200||source!=null&&source.length()>300)throw new IllegalArgumentException("图片说明长度超过限制。");var file=r.getPart("image");var stored=ImageStorage.save(file);new PlantDao().addImage(plantId,stored.name(),alt,source);new AuditDao().log(WebSupport.user(r).getId(),"IMAGE_UPLOAD","plant",plantId,stored.name(),r.getRemoteAddr());r.getSession().setAttribute("flash","图片上传成功。");}catch(Exception e){r.getSession().setAttribute("flash","图片上传失败："+e.getMessage());}s.sendRedirect(r.getContextPath()+"/admin/plants/form?id="+id);}}
